def length_of_longest_substring(s):
    last_seen = {}                      # character -> index of its latest occurrence
    start = best = 0                    # the window s[start : i + 1] has no repeated character
    for i, ch in enumerate(s):
        if ch in last_seen and last_seen[ch] >= start:
            start = last_seen[ch] + 1   # the window must begin after the earlier copy
        last_seen[ch] = i
        best = max(best, i - start + 1)
    return best
